import json
import os

# Load demos
program_dir = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference/play/users/u068/system/state/workspace/programs"
task_id = "task-cfa68595"
json_path = os.path.join(program_dir, f"{task_id}.json")
with open(json_path, 'r') as f:
    demos = json.load(f)

input1 = demos[0]['input']
output1 = demos[0]['output']

# Get input 3x3 blocks
def get_input_blocks(grid):
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(3):
        for c in range(3):
            block = grid[r*3:(r+1)*3][c*3:(c+1)*3]
            blocks.append(block)
    return blocks

input_blocks = get_input_blocks(input1)

# Block properties
def block_has_8(block):
    for row in block:
        if 8 in row:
            return True
    return False

def block_has_4(block):
    for row in block:
        if 4 in row:
            return True
    return False

def block_8_count(block):
    total = 0
    for row in block:
        for val in row:
            if val == 8:
                total += 1
    return total

def block_4_count(block):
    total = 0
    for row in block:
        for val in row:
            if val == 4:
                total += 1
    return total

print("--- Input blocks analysis ---")
for i, block_rows in enumerate(input_blocks):
    row_idx = i // 3
    col_idx = i % 3
    has_8 = block_has_8(block_rows)
    has_4 = block_has_4(block_rows)
    c8 = block_8_count(block_rows)
    c4 = block_4_count(block_rows)
    center = block_rows[1][1] if len(block_rows) > 1 and len(block_rows[1]) > 1 else None
    print(f"Block ({row_idx},{col_idx}): 8s={has_8}, 4s={has_4}, c8={c8}, c4={c4}, center={center}")

# Output conceptual grid
output_w = len(output1[0]) // 2
conceptual_output = [[0]*output_w for _ in range(len(output1))]
for r, row in enumerate(output1):
    for c in range(output_w):
        conceptual_output[r][c] = row[2*c]

print("\n--- Conceptual output 3x3 ---")
for row in conceptual_output:
    print(row)

# Compare: do output values match some property of corresponding blocks?
print("\n--- Comparing blocks to output ---")
for r in range(3):
    for c in range(3):
        block = input_blocks[r*3 + c]
        print(f"Block ({r},{c}) -> Output {conceptual_output[r][c]}: has_8={block_has_8(block)}, has_4={block_has_4(block)}, c8={block_8_count(block)}, c4={block_4_count(block)}")

# Submit with centered beams
action ={"action": "submit", "grid": [[0, 0, 8, 8, 0, 0], [8, 8, 8, 8, 8, 8], [0, 0, 0, 0, 0, 0]]}
print(action)

